Here's a code snippet that shows how to create a simple interface displaying the "UP" and "DOWN" buttons with a text area in between using Qt in C++:

```
#include <QApplication>
#include <QWidget>
#include <QPushButton>
#include <QTextEdit>
#include <QVBoxLayout>

int main(int argc, char *argv[])
{
    QApplication app(argc, argv);

    QWidget window;
    window.setWindowTitle("Up Down Buttons");

    // Create buttons
    QPushButton *upButton = new QPushButton("UP");
    QPushButton *downButton = new QPushButton("DOWN");

    // Create text area
    QTextEdit *textArea = new QTextEdit();

    // Add buttons and text area to a vertical layout
    QVBoxLayout *layout = new QVBoxLayout();
    layout->addWidget(upButton);
    layout->addWidget(textArea);
    layout->addWidget(downButton);

    // Set widget layout
    window.setLayout(layout);

    window.show();

    return app.exec();
}
```

This code creates a `QPushButton` for the "UP" button and another one for the "DOWN" button, as well as a `QTextEdit` for the text area. It then adds these widgets to a vertical layout using `QVBoxLayout`, and sets this layout as the widget's layout using `setLayout()`. Finally, it shows the widget and starts the Qt event loop using `show()` and `app.exec()` respectively.
